return {["dinner"]={["1"]={["attrAward"]=[[yinpiao,100;money,50000]],["baseAward"]=[[2021yxyawards]],["day"]=[[除夕]],["foodDemand"]=[[2021yxyneed1,5;2021yxyneed2,3;2021yxyneed3,10;2021yxyneed4,5;2021yxyneed5,12;2021yxyneed6,6]],["id"]=1,["introText"]=[[除夕团圆饭，讲究面面俱到，色香味俱全加上阖家团聚，才是一桌好饭。]],["name"]=[[合家团圆]],["wine1Hero"]=[[hero48]],["wine1Text"]=[[text220,text221,text222,text223,text224]],["wine2Hero"]=[[hero12]],["wine2Text"]=[[text52,text53,text54,text55,text56]],["wine3Hero"]=[[hero11;hero39]],["wine3Text"]=[[text46,text47,text48,text49,text50,text51]],["wine4Hero"]=[[hero5;hero42]],["wine4Text"]=[[text19,text20,text21,text22,text23,text24,text25]],["wine5Hero"]=[[hero6]],["wine5Text"]=[[text26,text27,text28,text29,text30,text31]]},["2"]={["attrAward"]=[[yinpiao,100;money,50000]],["baseAward"]=[[2021yxyawards]],["day"]=[[初一]],["foodDemand"]=[[2021yxyneed1,24;2021yxyneed2,6;2021yxyneed3,12]],["id"]=2,["introText"]=[[大年初一，吃香喝辣，朝着新的一年，新的冒险出发！]],["name"]=[[万象更新]],["wine1Hero"]=[[hero28;hero29]],["wine1Text"]=[[text139,text140,text141,text142,text143,text144]],["wine2Hero"]=[[hero3;hero4]],["wine2Text"]=[[text13,text14,text15,text16,text17,text18]],["wine3Hero"]=[[hero20]],["wine3Text"]=[[text93,text94,text95,text96,text97,text98]],["wine4Hero"]=[[hero1]],["wine4Text"]=[[text1,text2,text3,text4,text5,text6,text7]],["wine5Hero"]=[[hero49]],["wine5Text"]=[[text225,text226,text227,text228,text229]]},["3"]={["attrAward"]=[[yinpiao,100;money,50000]],["baseAward"]=[[2021yxyawards]],["day"]=[[初二]],["foodDemand"]=[[2021yxyneed3,10;2021yxyneed4,5;2021yxyneed5,12;2021yxyneed6,8]],["id"]=3,["introText"]=[[大年初二，紫气浮关从东至，吉星高照，吃出如意顺心事。]],["name"]=[[紫气东来]],["wine1Hero"]=[[hero34]],["wine1Text"]=[[text165,text166,text167,text168,text169]],["wine2Hero"]=[[hero50]],["wine2Text"]=[[text244,text245,text246,text247,text248,text249]],["wine3Hero"]=[[hero41;hero26]],["wine3Text"]=[[text127,text128,text129,text130,text131,text132]],["wine4Hero"]=[[hero51]],["wine4Text"]=[[text234,text235,text236,