]],["pic"]=[[Image/UI/AttrUI/mianju/mingjiaoshengnv.png]]},["hero48"]={["award"]=[[guestaward48]],["id"]=[[hero48]],["name"]=[[段潇]],["pic"]=[[Image/UI/AttrUI/mianju/duanxiao.png]]},["hero49"]={["award"]=[[guestaward49]],["id"]=[[hero49]],["name"]=[[花公子]],["pic"]=[[Image/UI/AttrUI/mianju/huagongzi.png]]},["hero5"]={["award"]=[[guestaward5]],["id"]=[[hero5]],["name"]=[[神僧]],["pic"]=[[Image/UI/AttrUI/mianju/shenseng.png]]},["hero50"]={["award"]=[[guestaward50]],["id"]=[[hero50]],["name"]=[[叶妄生]],["pic"]=[[Image/UI/AttrUI/mianju/yewangsheng.png]]},["hero51"]={["award"]=[[guestaward51]],["id"]=[[hero51]],["name"]=[[欧冶子]],["pic"]=[[Image/UI/AttrUI/mianju/ouyezi.png]]},["hero52"]={["award"]=[[guestaward54]],["id"]=[[hero52]],["name"]=[[洪老帮主]],["pic"]=[[Image/UI/AttrUI/mianju/hongqigong.png]]},["hero53"]={["award"]=[[guestaward52]],["id"]=[[hero53]],["name"]=[[肖老]],["pic"]=[[Image/UI/AttrUI/xinwu/xinwu200_08.png]]},["hero54"]={["award"]=[[guestaward55]],["id"]=[[hero54]],["name"]=[[雨珊]],["pic"]=[[Image/UI/AttrUI/xinwu/xinwu200_10.png]]},["hero55"]={["award"]=[[guestaward53]],["id"]=[[hero55]],["name"]=[[蒙古郡主]],["pic"]=[[Image/UI/AttrUI/mianju/menggujunzhu.png]]},["hero6"]={["award"]=[[guestaward6]],["id"]=[[hero6]],["name"]=[[梅大侠]],["pic"]=[[Image/UI/AttrUI/mianju/meiniansheng3.png]]},["hero7"]={["award"]=[[guestaward7]],["id"]=[[hero7]],["name"]=[[木姑娘]],["pic"]=[[Image/UI/AttrUI/mianju/muwanqin.png]]},["hero8"]={["award"]=[[guestaward8]],["id"]=[[hero8]],["name"]=[[钟姑娘]],["pic"]=[[Image/UI/AttrUI/mianju/zhongling.png]]},["hero9"]={["award"]=[[guestaward9]],["id"]=[[hero9]],["name"]=[[宋清秋]],["pic"]=[[Image/UI/AttrUI/mianju/songqingqiu.png]]}},["text"]={["text1"]={["id"]=[[text1]],["text"]=[[就在你刚坐下时，突然听到门外传来几声爽朗的笑声，一名男子高声说道：“如此美酒，如此佳节，怎能少得了我章某人？！”]]},["text10"]={["id"]=[[text10]],["text"]=[[|#AAAA宴席既开，黑市商人只专注吃饮，极少言语，你主动为他斟酒一杯，邀他品尝。]]},["text100"]={["id"]=[[text100]],["text"]=[[|#AAAA你将程姑娘引入宴席，因外头冰寒，入屋后她的发髻上结了一层冰霜。她浅笑着朝你看来，道了一声“新春快乐”。]]},["text101"]={["id"]=[[text101]],["text"]=[[|#AAAA席间灯影摇曳，将她原本枯黄的肌肤衬的更无光彩，但独独那双眼睛明亮至极让人难忘。]]},["text102"]={["id"]=[[text102]],["text"]=[[|#AAAA随后，你朝程姑娘敬了一杯酒，她略低眸，恍惚道：“江湖中我少有友人，只一本书，一株海棠，还有大哥......”]]},["text103"]={["id"]=[[text103]],["text"]=[[|#AAAA你微微怔住，夹了一道菜送往程姑娘的碗中，笑道：“姑娘若不嫌弃，算我一个可好？”]]},["text104"]={["id"]=[[text104]],["text"]=[[正要开席，忽听一个声音传来：“无量寿佛，贫道打扰了。”只见一个道士打扮的男子径直走了进来。]]},["text105"]={["id"]=[[text105]],["text"]=[[|#AAAA原来是失踪多日、传闻已外出云游、寻访仙药的王真一。]]},["text106"]={["id"]=[[text106]],["text"]=[[|#AAAA管家将王真一引上宴席。王真一似乎谈兴颇浓，侃侃而谈，说起了这些日子以来的种种见闻，说得唾沫横飞、手舞足蹈。]]},["text107"]={["id"]=[[text107]],["text"]=[[|#AAAA“敢问，可能长生？”你试探地问道。]]},["text108"]={["id"]=[[text108]],["text"]=[[|#AAAA“不知。”王真一敛容道。]]},["text109"]={["id"]=[[text109]],["text"]=[[|#AAAA“欲往何处？”你接着问。]]},["text11"]={["id"]=[[text11]],["text"]=[[|#AAAA黑市商人似对这女儿红酒极为喜欢，约莫不久便喝空一坛，连饭菜也所剩不多，唯你腹中空空，你无奈地笑着摇头，遂赶忙也吃上了几口。也不过是低头夹菜的功夫，再抬头黑市商人已然不见。]]},["text110"]={["id"]=[[text110]],["text"]=[[|#AAAA“天之涯，海之角。”王真一面露微笑，如同拈花的尊者。]]},["text111"]={["id"]=[[text111]],["text"]=[[|#AAAA夜已阑珊，长街初静，空中似有雪花落下。]]},["text112"]={["id"]=[[text112]],["text"]=[[你走入席间，忽听得门外有人叫唤起来，“少侠，有此等好酒为何不等我一起？”未见其人，但闻其声定是大理段公子。]]},["text113"]={["id"]=[[text113]],["text"]=[[|#AAAA你即刻命管家添上碗筷，迎上前去，只笑称不敢与段公子比酒，生怕他使诈用内功将酒水逼出，自己岂不是必输无疑。]]},["text114"]={["id"]=[[text114]],["text"]=[[|#AAAA闻言，段公子略有几分羞赧。可话虽如此，你仍旧让管家抬出了几坛好酒，誓要与他一醉方休。]]},["text115"]={["id"]=[[text115]],["text"]=[[|#AAAA酒肉入肠，你们纷纷谈论当初在大理所遇险境，又说起这江湖风云变幻，酒醉迷糊间一齐走出屋外，耍起了剑招。]]},["text116"]={["id"]=[[text116]],["text"]=[[|#AAAA最后，也不知谁说了一句：“新年如此，快哉！”]]},["text117"]={["id"]=[[text117]],["text"]=[[管家刚来请你入席，你便已经嗅到了席间菜肴的香味，正欲坐下，抬眼间一个白衣女子面纱遮面倚在门口婀娜地望着你。]]},["text118"]={["id"]=[[text118]],["text"]=[[|#AAAA只听得她声音轻柔婉转，“少侠好兴致，怎么不派人邀我一同品尝珍馐？”原是李仙姑到访。]]},["text119"]={["id"]=[[text119]],["text"]=[[|#AAAA你笑了笑，起身相迎。李仙姑绕着屋内走了一圈，最后停在一碟名为“玲珑玉心”的菜前。]]},["text12"]={["id"]=[[text12]],["text"]=[[|#AAAA忽听院中人声回荡，“劳少侠今日款待，他朝若有好货必当来寻，告辞！”]]},["text120"]={["id"]=[[text120]],["text"]=[[|#AAAA管家正好捧来一坛竹叶青，李仙姑便自饮了起来，不时称赞几句菜肴美味可口，又说这“玲珑玉心”极似一块美玉。]]},["text121"]={["id"]=[[text121]],["text"]=[[|#AAAA酒酣宴罢，李仙姑半醉颤笑，转身离去，留话道：“多谢今日款待，他日江湖再遇可要当心呐。”]]},["text122"]={["id"]=[[text122]],["text"]=[[管家才请你入席，门外就传来小厮的声音，“燕子坞慕容公子求见你家主人。”]]},["text123"]={["id"]=[[text123]],["text"]=[[|#AAAA没多久，几个小厮抬着一盒漆木红箱走了进来，后面是一锦衣男子，男子甚是俊美潇洒，便是慕容公子。]]},["text124"]={["id"]=[[text124]],["text"]=[[|#AAAA慕容公子上前，彬彬有礼，“新春到访多有打扰，在下特地送上薄礼，祝贺新年大吉大利。”]]},["text125"]={["id"]=[[text125]],["text"]=[[|#AAAA早闻慕容家有复兴燕国拉拢群雄之意，但今日新春你不愿谈及其他，于是将话题一转把慕容公子引入了宴席。]]},["text126"]={["id"]=[[text126]],["text"]=[[|#AAAA几杯酒水下肚，慕容公子见你兴致盎然也不再多说其他。你们相互言谈，倒有几分相知之情，也不枉这一席好酒。]]},["text127"]={["id"]=[[text127]],["text"]=[[宴席正要开始，便有人叩响了大门，一边嚷着“开门、开门”，一边又有清脆的金银首饰碰撞之声。]]},["text128"]={["id"]=[[text128]],["text"]=[[|#AAAA江湖中这般活泼灵秀的女子甚少，你大概猜中来者身份，连忙起身相迎，郭二小姐和丁红蝶就脚步轻快的跑了进来。]]},["text129"]={["id"]=[[text129]],["text"]=[[|#AAAA郭二小姐眨了眨眼睛，指尖虚掩红唇轻笑道：“我们今年依然要来陪你过节”。丁红蝶则直接坐在了酒桌前，倒了一口剑南春酒。]]},["text13"]={["id"]=[[text13]],["text"]=[[你刚刚走至宴桌前，忽听门外几声马蹄，又有侍者压轿叫唤之声，紧跟着仆人来报有贵客到访。]]},["text130"]={["id"]=[[text130]],["text"]=[[|#AAAA“今年准备的酒真不错，小丫头你快来尝尝。”丁红蝶点着头看向郭二小姐。]]},["text131"]={["id"]=[[text131]],["text"]=[[|#AAAA一侧郭二小姐叫嚷着跑来，只道：“说过不要叫我小丫头，你年龄看起来也不比我大。”]]},["text132"]={["id"]=[[text132]],["text"]=[[|#AAAA二人一时斗嘴，一时又合力捉弄你一番，屋里屋外瞬间热闹非凡，让你想起去年此时，也是这般心情畅快，似乎因为有她们出现，关于新年的记忆多了一层暖色。]]},["text133"]={["id"]=[[text133]],["text"]=[[宴席正要开始，院外便传来扣门之声，管家快步前去开门，很快，林掌门和王重阳一同走进。]]},["text134"]={["id"]=[[text134]],["text"]=[[|#AAAA你见两人面色如常，不像去年过节时闹起争执，不由心下松了口气，起身将他们引入席间。]]},["text135"]={["id"]=[[text135]],["text"]=[[|#AAAA管家奉上清茶，林掌门却笑道：“素日听闻少侠这里不缺美酒，我今日是来向少侠讨酒喝”。王重阳亦是点头，只说是为酒结伴而来。]]},["text136"]={["id"]=[[text136]],["text"]=[[|#AAAA你哑然一笑，吩咐管家开坛上酒，你三人皆对武学兴浓，各抒已见，只是随着酒水愈进，反倒王重阳与林掌门聊得愈发热络，你竟半句也插不进。]]},["text137"]={["id"]=[[text137]],["text"]=[[|#AAAA无奈之下，你吃了几口吃食，忍不住大笑了起来。王重阳好奇看来，林掌门似懂你意，只是不曾解释半句。]]},["text138"]={["id"]=[[text138]],["text"]=[[|#AAAA一夜喜乐，回忆去年，结合今日，你忽想起那句：道是无晴却有晴。]]},["text139"]={["id"]=[[text139]],["text"]=[[你见宴上酒席已安置妥当甚是满意，正准备下筷，院外朗笑声传来。随后，令狐少侠怀抱美酒，大步迈入了屋子。]]},["text14"]={["id"]=[[text14]],["text"]=[[|#AAAA一股女子衣袖间的暗香袭来，再伴着男子爽朗的笑声，你一抬眼就对上了杨玉环的倾城笑意和王维明快的双眸。]]},["text140"]={["id"]=[[text140]],["text"]=[[|#AAAA你起身上前向他贺了几句新春佳节的吉利话，他毫不在意地摆了摆手，“你我何必这么多虚礼，喝酒就是。”]]},["text141"]={["id"]=[[text141]],["text"]=[[|#AAAA江湖儿女本就不拘小节，你点头称是，再转身时令狐少侠忙问你可曾丢了物件，你一时茫然。]]},["text142"]={["id"]=[[text142]],["text"]=[[|#AAAA不料，香帅竟从梁上跃下将你原放在腰间的物件送了出来，“我与令狐兄早就打赌，要取得你贴身物件，看来是我赢了。”]]},["text143"]={["id"]=[[text143]],["text"]=[[|#AAAA令狐少侠擦了擦嘴角的酒渍，将手中的酒坛递去：“可惜了这坛好酒，下次再与你赌，我偏不信世上万物你皆能取得。”]]},["text144"]={["id"]=[[text144]],["text"]=[[|#AAAA原是一场赌，你忙命管家又搬出几坛女儿红，打算今夜与他们二人一醉方休。]]},["text145"]={["id"]=[[text145]],["text"]=[[“咚，咚”宴席正要开始，门外就响起了叩门声。管家快步赶去开门，又听一声“有请”，大门才关上。]]},["text146"]={["id"]=[[text146]],["text"]=[[|#AAAA只见柳如烟迈进了门槛，朝你望来，“怎的少侠见了我似有些吃惊，莫不是不欢迎？”]]},["text147"]={["id"]=[[text147]],["text"]=[[|#AAAA你急忙摇头，将她请入了宴席。柳如烟倒也不似小女儿家拘谨，只让你速速将备好的竹叶青酒倒上来。]]},["text148"]={["id"]=[[text148]],["text"]=[[|#AAAA酒水既至，柳如烟站了起来，朝你一敬：“正逢佳节，我盛唐阁又岂会忘了少侠，今日前来一祝少侠新年愉快，二谢‘江湖有你’！”]]},["text149"]={["id"]=[[text149]],["text"]=[[|#AAAA随后，柳如烟满饮杯中之酒，朝你又是拱手一谢。你微微半愣，又怕她笑你拘泥，遂也一口将酒水喝尽，同她一夜畅聊。]]},["text15"]={["id"]=[[text15]],["text"]=[[|#AAAA当真是贵客到访。你起身相迎，将他们二人引入席间后先自斟了三杯，宴席既开，也并未再顾忌那些繁文缛节，各自洒脱起来。]]},["text150"]={["id"]=[[text150]],["text"]=[[新春佳节，酒宴虽然已经备好，但你总觉一人有些冷清，正想着管家便来报，郭少侠到访。]]},["text151"]={["id"]=[[text151]],["text"]=[[|#AAAA你速速命管家将郭少侠迎了上来，只见他身披长袄，甚是有礼道：“少侠，新春愉快。在下愚钝，也说不出个什么吉利话，海涵。”]]},["text152"]={["id"]=[[text152]],["text"]=[[|#AAAA几杯酒水下肚，郭少侠忽转头道：“我原与蓉儿一道，今日佳节我念起远在蒙古的阿母，蓉儿偏说我是想回去当驸马......”]]},["text153"]={["id"]=[[text153]],["text"]=[[|#AAAA你忙追问后来如何，郭少侠又说，“我哪忍心惹她生气，后她让我来此拜会少侠，莫要回去了。”]]},["text154"]={["id"]=[[text154]],["text"]=[[|#AAAA郭少侠又饮了一口酒，你不知当不当点破黄姑娘之意。随后瑞雪飘散，你们饮酒至深夜，接连把这一年来的烦忧抛个干净。]]},["text155"]={["id"]=[[text155]],["text"]=[[你刚刚入席，门外便有一黑衣侠客来访，面色苍白，似身有病疾。他一语不发，只微微低着眸，抱着一把长刀。]]},["text156"]={["id"]=[[text156]],["text"]=[[|#AAAA管家不识他名号，你摆摆手，命其只管上酒就是。黑衣侠客缓缓坐入席间，你向他敬了一杯酒，道了句新年大吉。]]},["text157"]={["id"]=[[text157]],["text"]=[[|#AAAA宴席期间，他仍旧不把怀中长刀放下，你忽也取出了自己常用的兵刃，如他般抱在怀中。]]},["text158"]={["id"]=[[text158]],["text"]=[[|#AAAA良久，你实在忍受不住这般饮酒吃肉，同他道：“即便江湖再穷凶之人，今夜佳节怕也顾不得这些恩怨吧。”]]},["text159"]={["id"]=[[text159]],["text"]=[[|#AAAA最后，黑衣侠客手中的刀仍未放下过一刻，但你已从他目光中感受到了笑意，虽不明显，但你确信他曾笑了。]]},["text16"]={["id"]=[[text16]],["text"]=[[|#AAAA酒过三巡，众人皆酒醉微醺，却兴致盎然。王维即命随行的小厮抱来了一张七弦古琴，杨玉环知他用意，忙扶桌掩笑叫好。]]},["text160"]={["id"]=[[text160]],["text"]=[[宴未开，你先饮了一口茶，准备去去口中的杂味，正巧有人叩门，紧跟着管家来报说王家才女前来拜访。]]},["text161"]={["id"]=[[text161]],["text"]=[[|#AAAA屋内灯火通明，王家才女步履缓慢地入了席，“早前就想拜访尊驾，趁此佳节愿祝阁下喜乐安康，事事如意。”]]},["text162"]={["id"]=[[text162]],["text"]=[[|#AAAA你心中好奇，发言相问她怎会独自一人，原来她随表兄到此办事，听闻你家住于此，特意上门恭贺新春。]]},["text163"]={["id"]=[[text163]],["text"]=[[|#AAAA你斟了杯清茶朝她送去，想起江湖曾言她对各家功夫见解独到，于是酒足饭饱后也忍不住问上几句。]]},["text164"]={["id"]=[[text164]],["text"]=[[|#AAAA王家才女谦笑，便让你耍了几招，然后一一点明、指出其中破绽，令你受益匪浅。当夜，你们二人以武为道，结为知己好友。]]},["text165"]={["id"]=[[text165]],["text"]=[[你坐入了宴席中，管家在旁正一一介绍桌上的菜名，随后有两声低鸣怪异的啼叫传来。你迅速起身，到门口一望——果然是神雕。]]},["text166"]={["id"]=[[text166]],["text"]=[[|#AAAA当下管家微愣，随后又特地为神雕备上了一方长椅。你倒了一杯酒，忙说道：“如此新春之际，得雕兄到访蓬荜生辉！”]]},["text167"]={["id"]=[[text167]],["text"]=[[|#AAAA神雕极通人性，虽不能同你一起碰碗吃酒，畅聊畅饮，却发出了长长的啼叫之声以作回答。]]},["text168"]={["id"]=[[text168]],["text"]=[[|#AAAA管家初时不解，但看你说一句神雕便啼叫一句，到了高兴时啼叫声也尽不相同，最后习以为常，不时为你添酒添菜。]]},["text169"]={["id"]=[[text169]],["text"]=[[|#AAAA一雕一人，就这般简单地共度了新春，来日江湖上不免又多了一桩美谈。]]},["text17"]={["id"]=[[text17]],["text"]=[[|#AAAA琴音拨动，一如清泉石上流，一如松间明月照。杨玉环身穿绫罗长裙，起身随琴而舞，飘飘然如月下瑶台仙。]]},["text170"]={["id"]=[[text170]],["text"]=[[管家这头才来请你入宴，那头树梢上一抬眼你就看到了一个长相白净，穿着很是随意的少年正咧着嘴朝你一笑。]]},["text171"]={["id"]=[[text171]],["text"]=[[|#AAAA“尊驾，你家中倒是有好酒，我寻着就来了。”他纵身跳下了树梢，快步走了过来。]]},["text172"]={["id"]=[[text172]],["text"]=[[|#AAAA青年也不拘礼，随意地吃了几筷子，只称你家中的厨子所做饭菜滋味甚是不错。]]},["text173"]={["id"]=[[text173]],["text"]=[[|#AAAA想这一年所遇江湖侠士，如他这般时时开心之人少之又少，更别说洒脱不羁。]]},["text174"]={["id"]=[[text174]],["text"]=[[|#AAAA不过数语，你便觉得与他相逢恨晚，连桌上酒菜也都忘了下筷，只一个劲儿说着江湖所历，不时出招比划，颇为自在。]]},["text175"]={["id"]=[[text175]],["text"]=[[你刚刚准备开宴，门外就有客到，看管家递上来的拜帖，正是金钱帮的掌柜沈元龙。]]},["text176"]={["id"]=[[text176]],["text"]=[[|#AAAA沈元龙径直朝你走来，拱手道：“在下谨代表金钱帮特来拜会，多有打扰。”]]},["text177"]={["id"]=[[text177]],["text"]=[[|#AAAA你将沈元龙请入了宴席，介绍了几个宴上的名菜，沈元龙微微点头，举动间颇有风范，礼数周全，倒让你觉得有些见外。]]},["text178"]={["id"]=[[text178]],["text"]=[[|#AAAA后因你饮了些酒，拉扯着沈元龙谈起江湖之事，沈元龙仔细聆听，不时也说道些心中所感，一时宾主尽欢。]]},["text179"]={["id"]=[[text179]],["text"]=[[|#AAAA宴会最后，沈元龙再次起身相谢，“此一年有劳尊驾江湖仗义，来日江湖前行，金钱帮也必随左右，阁下若有需要直说便是。”]]},["text18"]={["id"]=[[text18]],["text"]=[[|#AAAA你也不落人后，拔剑助兴，高歌而和，一时间觥筹交错，宾主尽欢。]]},["text180"]={["id"]=[[text180]],["text"]=[[宴上，管家将屠苏酒搬了出来，你刚刚尝了一口，门外就有敲门声响起。随后，平遥公主走了进来。]]},["text181"]={["id"]=[[text181]],["text"]=[[|#AAAA你本江湖人士，不受那些个宫规拘束，所以也无需行大礼，只当作平常人般将平遥公主迎了进来。]]},["text182"]={["id"]=[[text182]],["text"]=[[|#AAAA不料平遥公主扬眉，微抬嘴角道：“你若要本宫赴宴，需先赢了本宫，不然不去。”]]},["text183"]={["id"]=[[text183]],["text"]=[[|#AAAA宴已开，你生怕菜肴冷去失了味道，只好答允。后与平遥公主以拳脚论输赢，这才将她请入了宴席。]]},["text184"]={["id"]=[[text184]],["text"]=[[|#AAAA她起初因为输给你，面上颇为不喜，后喝了一口屠苏酒便露出女儿本性，倒多了几分灵动之气，同你也是说说笑笑，如此欢度新春。]]},["text185"]={["id"]=[[text185]],["text"]=[[管家刚刚将你引入了席间，就有帖子送了进来，上书：盛唐阁秋珊灵拜会。]]},["text186"]={["id"]=[[text186]],["text"]=[[|#AAAA不多时，管家领着一清丽女子走了上来，正是秋珊灵。她浅浅一笑，朝你恭贺道：“新春有礼，吉祥如意！”]]},["text187"]={["id"]=[[text187]],["text"]=[[|#AAAA你朝她一点头，将她引入了宴席。秋珊灵望了望席间菜肴，忽然道：“如烟喜酒我却喜茶，不知少侠知不知道？”]]},["text188"]={["id"]=[[text188]],["text"]=[[|#AAAA不等她说完，你已斟了两杯香茶。茶香悠然，两叶漂浮犹如山海青龙，你由此想起丐帮降龙“双龙取水”之势，与秋珊灵谈及。]]},["text189"]={["id"]=[[text189]],["text"]=[[|#AAAA秋珊灵听得津津有味，又向你讨教了不少武学招式，相谈甚欢。]]},["text19"]={["id"]=[[text19]],["text"]=[[宴席即开，你正要召唤管家上桌一起吃个团圆饭时，一个文士打扮的青年男子冒冒失失地闯了进来。]]},["text190"]={["id"]=[[text190]],["text"]=[[正要开席之际，管家却不知去了哪。不一会儿，一家丁回报，说是管家在门口拦住了一名异邦女子。异邦女子？你不由心中一动，莫非是她？]]},["text191"]={["id"]=[[text191]],["text"]=[[|#AAAA你连忙奔向门外，定睛望去，门外女子身着红色骑士服，蓝色眼睛灿若星辰，正是重光教的卡米尔！]]},["text192"]={["id"]=[[text192]],["text"]=[[|#AAAA卡米尔问道：“昔日一别，阁下便是如此对待朋友的？”你连忙致歉，引卡米尔入席。]]},["text193"]={["id"]=[[text193]],["text"]=[[|#AAAA刚一入席，卡米尔道：“我家乡的酒你是否尝过？”说罢，卡米尔取出一个红瓶，倒出酒来，酒色棕红，你尝了一口，只觉甘美异常。]]},["text194"]={["id"]=[[text194]],["text"]=[[|#AAAA酒过三巡，你二人均有微醺之意。卡米尔谈起她的故国、童年、成为骑士的经历和前往中土的旅程……你端坐椅上，仔细听着，愈发佩服这女骑士的坚强和勇敢。]]},["text195"]={["id"]=[[text195]],["text"]=[[|#AAAA饮至酣处，卡米尔取出刺剑，在夜色下挥剑若舞，舞动剑随。一时间，你已分不清这是剑术还是舞蹈，恍惚间，已然看痴了。]]},["text196"]={["id"]=[[text196]],["text"]=[[|#AAAA宴罢，你要送卡米尔一程。卡米尔道：“中土与我故国相距万里，我既只身前来，又何需人送，阁下留步。”说罢，大踏步的离开了。你看着她离去的背影，你不由心中感叹，怅然若失。]]},["text197"]={["id"]=[[text197]],["text"]=[[正要开宴，你听见外头小厮喊了一声“下雪了”，你推开木窗，却见沐临烟身披红狐斗篷立于廊下枫树旁，对你盈盈笑道：“我让管家不必通报，本想给少侠一个惊喜，谁知被逮了个正着。”]]},["text198"]={["id"]=[[text198]],["text"]=[[|#AAAA你将沐临烟迎进宴席，酒过三巡，她起身拿起了琵琶，“临烟不胜酒力，不能再饮了，便弹奏一曲给少侠助兴吧。”]]},["text199"]={["id"]=[[text199]],["text"]=[[|#AAAA因喝了些酒，沐临烟脸色泛红，神态一改过往，少了半分端庄，多了些许娇媚，随后，她轻抚琴弦，一曲琵琶已然弹起。]]},["text2"]={["id"]=[[text2]],["text"]=[[|#AAAA男子说话间，已阔步走了进来，你定眼一看，竟是章作之。]]},["text20"]={["id"]=[[text20]],["text"]=[[|#AAAA“来者何人？”管家一脸戒备地盯着青年男子，青年摇摇手中的扇子，自报家门：]]},["text200"]={["id"]=[[text200]],["text"]=[[|#AAAA只见她轻拨重挑，快弹慢拢，时而五指齐拂，时而分指飞弹。柔时如弱水无形，坚时如金器相击。乱时如乌云压顶，齐时如布阵排兵……一曲弹罢，你许久才从琴声中醒来。]]},["text201"]={["id"]=[[text201]],["text"]=[[|#AAAA酒宴终了，沐临烟与你一起至庭前散步，沐临烟借着酒兴踩着庭中矮石折下了一枝红梅朝你递来。]]},["text202"]={["id"]=[[text202]],["text"]=[[|#AAAA她盈盈对你笑道：“愿明年此时，还能与少侠闲步院中，无忧无愁，笑傲凌云。”]]},["text203"]={["id"]=[[text203]],["text"]=[[你缓缓入席，满桌佳肴便是轻嗅一口也饱了三分，正当你犹豫不知从何下筷时，忽听一声“少侠，今日团圆饭就添我一副碗筷如何？”]]},["text204"]={["id"]=[[text204]],["text"]=[[|#AAAA你出门一瞧，竟是凌云来了。管家见凌云身穿官服，正要跪拜，突想起去年凌云所言，于是只友好地一笑，不再拘于那些繁文缛节。]]},["text205"]={["id"]=[[text205]],["text"]=[[|#AAAA凌云对此格外高兴，笑道：“如今我来这里竟似回家般亲切。”这话瞬间拉近大家的距离，随后由你亲自将凌云引入席中。]]},["text206"]={["id"]=[[text206]],["text"]=[[|#AAAA你和凌云谈起彼此最近的经历，他诉说自己如何机智破案，你也道出自己在武学上新的见解，你二人说到得意之处，均是哈哈大笑。]]},["text207"]={["id"]=[[text207]],["text"]=[[|#AAAA旁边管家不时为你们温酒布菜，凌云依然极是能饮，数坛美酒下肚毫无醉意，直言你这里的剑南春酒比别处多些滋味，你说送他几坛，他却摆手拒绝道：“只有这等佳节与少侠共饮，这酒才喝得过瘾！”]]},["text208"]={["id"]=[[text208]],["text"]=[[宴席即开，你正要召唤管家上桌一起吃个团圆饭时，忽听房顶有人说道：“少侠，萧某人我给你送美酒来了！”]]},["text209"]={["id"]=[[text209]],["text"]=[[|#AAAA你望向屋顶，只见萧侠盗在空中几个腾挪，宛若游龙，潇洒落地。]]},["text21"]={["id"]=[[text21]],["text"]=[[|#AAAA“承蒙江湖同道抬爱，给在下起了个绰号神僧，呵呵，惭愧惭愧……”青年男子嘴上说着惭愧，脸上却是一副得意洋洋的样子。]]},["text210"]={["id"]=[[text210]],["text"]=[[|#AAAA萧侠盗取出两坛美酒，置于桌上，笑道：“这两坛酒却是我三百里外一家恶霸那里拿来的，那恶霸欺男霸女，无恶不作。我把他教训而了一番，顺带拿了两坛美酒，痛快痛快！”]]},["text211"]={["id"]=[[text211]],["text"]=[[|#AAAA你与萧侠盗畅饮美酒，谈论江湖上快意恩仇的趣事，均是心中喜悦，倍增知己之感。]]},["text212"]={["id"]=[[text212]],["text"]=[[|#AAAA宴罢，萧侠盗一个鹞子翻身纵上屋顶，飘然而去。你心中感叹，此人当真是无比潇洒。]]},["text213"]={["id"]=[[text213]],["text"]=[[正要开宴之际，管家回报明教圣女来访。你心中惊讶，出门迎接，却见门外四个西域大汉抬着一顶轿子，一女子面带紫色轻纱端坐轿中。]]},["text214"]={["id"]=[[text214]],["text"]=[[|#AAAA见你出来，那女子才下了轿，虽戴了面纱，却也难掩美貌。她身材婀娜，眉目之间和中土女子完全不同，有着胡人女子独特美感。]]},["text215"]={["id"]=[[text215]],["text"]=[[|#AAAA众人入席，正要开席，却见明教圣女双手连拍三下，三名大汉便各捧了一坛酒走了进来，其中一个大汉又从轿中捧出了一只锦盒，盒内所装乃是一只西域夜光杯。]]},["text216"]={["id"]=[[text216]],["text"]=[[|#AAAA大汉将给你斟了酒，明教圣女举杯道：“我以茶代酒，你喝这葡萄酒，请！”]]},["text217"]={["id"]=[[text217]],["text"]=[[|#AAAA你举杯示意，随后将杯中酒一口饮尽，只觉甘甜可口，果香四溢。]]},["text218"]={["id"]=[[text218]],["text"]=[[|#AAAA宴上，你和明教圣女畅谈明教教义，对明教之济世理念又有了新的理解。]]},["text219"]={["id"]=[[text219]],["text"]=[[|#AAAA酒宴结束，你将明教圣女送至门外，明教圣女道：“我明教能在中土有少侠这样的朋友，实是我明教之幸。”说完她便上了轿子，缓缓消失在了远方。]]},["text22"]={["id"]=[[text22]],["text"]=[[|#AAAA正说话间，一个头戴孙大圣面具、身形高挑的人闯了进来。管家正要上前喝问，来者却先开腔了：“我乃神僧之友，唔唔，叫我大圣便可。”听声音，似乎是个妙龄女子。]]},["text220"]={["id"]=[[text220]],["text"]=[[酒席安排妥当，你吩咐管家将女儿红开坛，这时门外响起敲门声。没一会，身穿白衣的段潇走了进来。]]},["text221"]={["id"]=[[text221]],["text"]=[[|#AAAA“这等好酒，不知小可能否有幸讨两杯品尝？”段潇把玩手中的白扇，语气对你颇为亲近。]]},["text222"]={["id"]=[[text222]],["text"]=[[|#AAAA你当即爽朗大笑，并邀请他入座，一边与他畅饮，一边闲聊往昔，却都默契地不提当初在铁掌帮的那场争端。]]},["text223"]={["id"]=[[text223]],["text"]=[[|#AAAA外面的鞭炮声不绝于耳，宴上杯盏交错，欢颜笑语，又一坛美酒将空，你已有微醺之态，反观段潇仍然清醒，不由感慨他酒量见长。]]},["text224"]={["id"]=[[text224]],["text"]=[[|#AAAA宴罢，段潇突然提起沐临烟，但那时你醉得厉害，忘记自己是如何回话，只好似所有热闹褪尽，依稀记得他的一语叹息：“新的一年，唯愿……”]]},["text225"]={["id"]=[[text225]],["text"]=[[你刚入席不久，门外一位白衣少年缓步走来，虽衣着普通，但华贵的气质胜过世上任何锦衣玉带的公子，他朝你从容作揖，含笑道：“今日佳节路过贵地，能否向少侠讨一杯茶喝？”]]},["text226"]={["id"]=[[text226]],["text"]=[[|#AAAA百闻不如一见，只一眼你便对花公子心生好感，连忙起身邀他进屋共饮。]]},["text227"]={["id"]=[[text227]],["text"]=[[|#AAAA宴上你和他相谈甚欢，花公子见识不俗，谈吐文雅，说起江湖趣事绘声绘色，一旁的管家听得有如身临其境。]]},["text228"]={["id"]=[[text228]],["text"]=[[|#AAAA后来聊到武学奥义，你向花公子讨教“移花接玉”的武功，于是与他走去庭院中比试。]]},["text229"]={["id"]=[[text229]],["text"]=[[|#AAAA你二人交手数百个来回，不知不觉间竟一夜过去，眼见天明，切磋只好到此为止，花公子目光流露出对你的敬佩，离去前和你约定：“下回有机会定和少侠比个痛快！”]]},["text23"]={["id"]=[[text23]],["text"]=[[|#AAAA管家听了便冷哼一声：“一介凡人尔，岂敢称圣？”]]},["text230"]={["id"]=[[text230]],["text"]=[[你坐入宴席中，看着满桌精致的菜肴，不由食欲大振，正准备举筷品尝时，忽然面前菜盘里的一只烧鹅凭空消失。]]},["text231"]={["id"]=[[text231]],["text"]=[[|#AAAA管家一脸惊骇，左右寻找偷鹅之人，倒是你不慌不忙，仰头看向房梁道：“佳节之日，阁下既看得上这桌宴席，何不赏脸一同品尝。”]]},["text232"]={["id"]=[[text232]],["text"]=[[|#AAAA“哈哈哈，你这脾气老叫花我喜欢。”洪老帮主轻身跃下房梁，手里还抓着啃了几口的烧鹅。你见是他十分欢喜，连忙邀他入座。]]},["text233"]={["id"]=[[text233]],["text"]=[[|#AAAA对于桌上的这些菜肴，无需你介绍来历和做法，洪老帮主竟如数家珍，令你惊叹连连，到最后酒坛和菜盘被你们一扫而空。]]},["text234"]={["id"]=[[text234]],["text"]=[[管家刚引你入席坐下，小厮来报，说有个古怪的白发老头候在外面，你心有所感，快步奔到门外，定睛一瞧，来者正是欧冶子。]]},["text235"]={["id"]=[[text235]],["text"]=[[|#AAAA“今日佳节冒昧登门，少侠可欢迎？”欧冶子拱手笑言，你当即邀他入席。]]},["text236"]={["id"]=[[text236]],["text"]=[[|#AAAA在你授意之下，管家将准备好的剑南春打开，顿时一阵酒香沁人心脾，欧冶子却不急着饮酒，反而先考校你锻造之法学得如何。]]},["text237"]={["id"]=[[text237]],["text"]=[[|#AAAA几个问答来回之后，见你泰然自若，欧冶子眼睛半眯，语速越变越快，你跟着同速回话，以至于前音不散，尾音便起，满室残音重叠，如有千人不断问话，千人不断回话一般。]]},["text238"]={["id"]=[[text238]],["text"]=[[|#AAAA管家已然目瞪口呆，直到你难忍口干舌燥，面露无奈之色，欧冶子终于停住，举起酒杯大笑道：“快哉快哉，这杯酒敬少侠，祝少侠新春大吉！”言罢一饮而尽。]]},["text239"]={["id"]=[[text239]],["text"]=[[宴席即开，你团坐席间面对满桌菜肴正思考如何下筷，管家这时回禀说蒙古郡主前来拜访，随后，身穿白袍男装的美丽女子走进。]]},["text24"]={["id"]=[[text24]],["text"]=[[|#AAAA大圣：“孟子尝曰，人皆可以成尧舜，佛曰放下屠刀，立地成佛。如何不敢称圣？”]]},["text240"]={["id"]=[[text240]],["text"]=[[|#AAAA见你面露诧异，她笑盈盈道：“尊驾莫不是讨厌小妹，怎么有客来竟不主动迎接？”说话声娇娇嫩嫩，容光娇艳姿媚。]]},["text241"]={["id"]=[[text241]],["text"]=[[|#AAAA分明是她来得突然，倒先发制人，你顿觉好笑，赶紧邀她入席，斟茶与她赔罪。]]},["text242"]={["id"]=[[text242]],["text"]=[[|#AAAA杯中的茶叶起起伏伏，颜色鲜亮，蒙古郡主轻尝一口后满意地点头，飘渺的热气攀上她的眉眼，一张芙蓉面美得似云中仙子，举止间比寻常女子更多些英气豪态。]]},["text243"]={["id"]=[[text243]],["text"]=[[|#AAAA宴上，她谈吐甚健，不仅聊到武林中事信手拈来，连诗书字画也均钻研颇深，博识洽闻，令你听得如痴如醉，直到她指着窗外的启明星，祝你一声新春如意，你才发现窗外的天光已明……]]},["text244"]={["id"]=[[text244]],["text"]=[[管家引你团坐席间，你正欲举筷品尝菜肴，抬眼间便看见叶妄生静静站在门前，神情不辨喜怒。]]},["text245"]={["id"]=[[text245]],["text"]=[[|#AAAA管家不识他身份，满脸戒备地想上前叩问，你抬手制止，随后往杯中斟满酒水，甩手朝他掷去，边道：“既是熟人，不如留下入席，一同畅饮几杯。”]]},["text246"]={["id"]=[[text246]],["text"]=[[|#AAAA叶妄生跃身接住杯子，杯中酒水竟无一滴溢出，他仰头饮完酒，似笑非笑道：“少侠好客，在下也该敬少侠一杯。”]]},["text247"]={["id"]=[[text247]],["text"]=[[|#AAAA言罢，一根蛛丝从他袖中挥出，缠住桌上的空杯往酒坛中盛满酒水，眨眼间又将杯子朝你飞来。]]},["text248"]={["id"]=[[text248]],["text"]=[[|#AAAA你右掌运转内劲接下杯子，同样滴酒不洒，饮完，叶妄生拍掌叫好，“能接住在下酒杯的人，武林中少有！”]]},["text249"]={["id"]=[[text249]],["text"]=[[|#AAAA菜肴易冷，你再度邀他入席，待叶妄生坐下，你二人聊起刚才斗酒的招式，一番探讨下皆感武学大有进益，相谈甚欢。]]},["text25"]={["id"]=[[text25]],["text"]=[[|#AAAA你看他们眼看就要吵起来，连忙开口：“来者是客。既然来了，便一起入席吧。”众人皆落座。一场宴席下来，倒也宾主尽欢，颇为尽兴。]]},["text250"]={["id"]=[[text250]],["text"]=[[宴席正要开始，就有张帖子送了进来，上书：盛唐阁肖老拜会。]]},["text251"]={["id"]=[[text251]],["text"]=[[|#AAAA不多时，管家领着一高瘦文雅的男子走了上来，正是肖老。他朝你拱手贺道：“新春有礼，吉祥如意！”]]},["text252"]={["id"]=[[text252]],["text"]=[[|#AAAA你朝他一点头，将他引入了宴席，又瞧见他身侧还带着一个栩栩如生三尺高的男童傀儡，打扮神态像年画上的福娃，于是好奇地询问了几个关于傀儡的问题。]]},["text253"]={["id"]=[[text253]],["text"]=[[|#AAAA肖老笑着一一回答，当他提到这傀儡有奇异之处，会品酒验酒时，你忍不住吩咐管家打开酒坛，想亲眼见识。]]},["text254"]={["id"]=[[text254]],["text"]=[[|#AAAA随后一碗酒水被肖老倒入傀儡嘴中，那傀儡很快摇摇晃晃地站起身，似醉酒的高手般耍拳劈腿，末了，双手忽然展开一道新春贺联。]]},["text255"]={["id"]=[[text255]],["text"]=[[|#AAAA这一幕让你赞叹不已，肖老捋须笑言，“看来它对阁下的酒满意至极，若是寻常酒水，定然不会动作”。因有这傀儡助兴，这场酒宴你与肖老相谈甚欢。]]},["text256"]={["id"]=[[text256]],["text"]=[[宴席正要开始，便有人叩响了大门，管家快步赶去开门，又听一声“有请”，大门才关上。]]},["text257"]={["id"]=[[text257]],["text"]=[[|#AAAA只见雨珊如西子捧心，娇娇弱弱地迈进门槛，对你未语先笑，有些紧张不安。]]},["text258"]={["id"]=[[text258]],["text"]=[[|#AAAA你邀她入席坐下后，她看了眼满桌的菜肴，苍白的脸颊上浮现两抹羞红，声音怯怯地道：“盛唐阁派我来向少侠庆贺佳节，我体弱多病不得饮酒，能否以茶代替，敬少侠一杯？”]]},["text259"]={["id"]=[[text259]],["text"]=[[|#AAAA等她话落，你斟了两杯香茶，茶香悠然，雨珊品尝一口，瞪大了眼睛，直言好喝，再与你说话时，不像刚才那般拘谨。]]},["text26"]={["id"]=[[text26]],["text"]=[[望着面前的茶壶你甚是满意：因宴席上多是荤腥菜式，以茶代酒与这宴席正好相配。茶叶泡开，一时茶香四溢嗅如初春，门口管家忽来报：一位姓梅的大侠前来讨茶。]]},["text260"]={["id"]=[[text260]],["text"]=[[|#AAAA听闻雨珊常年极少外出，你与她聊起自己游历江湖时的所见所闻，她听得满脸向往之色，宴罢，你送她出门，临别前她回首朝你灿然一笑，妙目流光，道：“愿少侠如意安康，恣意江湖。”]]},["text27"]={["id"]=[[text27]],["text"]=[[|#AAAA你速速吩咐管家将梅大侠请入家中，自己也起身相迎。]]},["text28"]={["id"]=[[text28]],["text"]=[[|#AAAA只见梅大侠神色淡然道：“逢此佳节，各处酒肉寻常，独你这里清茶热汤，故老夫特意寻来。”]]},["text29"]={["id"]=[[text29]],["text"]=[[|#AAAA闻言，你转身捧茶朝梅大侠送去，听得两声“好茶，好茶”这宴席也就开了。]]},["text3"]={["id"]=[[text3]],["text"]=[[|#AAAA章作之已自己入了门，你忙起身拱手迎上，念及与他江湖初识之情，感慨万千，不想这般佳节竟能再度与他重逢饮酒。]]},["text30"]={["id"]=[[text30]],["text"]=[[|#AAAA席间忽谈及神功现世，梅大侠若有所思的朝你看来，便道这茶清如人，自己多有识人不清之时，但唯有一人自己从未看错。]]},["text31"]={["id"]=[[text31]],["text"]=[[|#AAAA茶水清淡，你忽听外头鞭炮齐鸣，邻里喜乐欢笑，口中滋味横生。看来，这新一年的江湖路会更远。]]},["text32"]={["id"]=[[text32]],["text"]=[[“少侠今日准备了什么样的好菜，好香啊！”你刚刚准备入席，只听门外传来女子清脆的声音，颇有灵韵。随后，管家引着两个女子走了上来。]]},["text33"]={["id"]=[[text33]],["text"]=[[|#AAAA钟姑娘最先跑来，伸手拿了一块宴上的糕点咬下，对着身后的女子道：“木姊姊，少侠这糕点依然如去年般好吃，你也快来尝尝。”]]},["text34"]={["id"]=[[text34]],["text"]=[[|#AAAA木姑娘浅浅一笑，朝你抱拳示意，“多有打扰”。你甚是开心地将她们二人引入宴席，说谈着近些日子的见闻。]]},["text35"]={["id"]=[[text35]],["text"]=[[|#AAAA酒暖菜香，听得一声鞭炮怦然炸响，钟姑娘开心地跑到窗前观望。木姑娘面露红晕，又喝了一杯酒，同你忆及去年过节之事。]]},["text36"]={["id"]=[[text36]],["text"]=[[|#AAAA宴尾将收，钟姑娘单手托腮倚在窗旁转头朝你看来，调笑着问你：“若有机会，少侠能否陪我去大理，看尽风花雪月。”]]},["text37"]={["id"]=[[text37]],["text"]=[[“如此盛宴，怎么能少了我呢，嘿嘿……”一个清脆的女声突然响起，只见一个身着黄色华服的少女大剌剌地走了进来。]]},["text38"]={["id"]=[[text38]],["text"]=[[|#AAAA看着少女一副人畜无害的样子，管家虽然抱着戒心，但还是语出温和地询问：“敢问这位贵人是……？”]]},["text39"]={["id"]=[[text39]],["text"]=[[|#AAAA少女捂嘴笑道：“奴家可不是什么贵人……路过此地，看着热闹，就不请自来了哈……如有唐突，多多包涵，嘿嘿……”她说话间双眼骨碌碌地乱转，打量着屋子的里里外外。]]},["text4"]={["id"]=[[text4]],["text"]=[[|#AAAA引席就坐后，管家匆忙上前招呼，章作之看了一眼面前的酒杯摇头笑说，“佳节在即，仅此杯中之物岂能尽兴。”]]},["text40"]={["id"]=[[text40]],["text"]=[[|#AAAA管家朝你看来，你不动声色地点头示意，管家随即开口：“相请不如偶遇，我家主人也是好客之人，贵客既然来了，就请入席吧，今儿是大年初一，图个吉利，也是极好的。”]]},["text41"]={["id"]=[[text41]],["text"]=[[|#AAAA少女闻言，眉开眼笑，也不客气，径直坐了下来。少女似乎是个自来熟的性子，言语诙谐、妙语连珠，一席间倒也是宾主尽欢。]]},["text42"]={["id"]=[[text42]],["text"]=[[你刚刚准备入席就有一个帖子递了进来，管家回禀道是一个清秀的姑娘来访，身上带着中草药的清香。不待他继续细说，你已知来访者定是岳凌薇。]]},["text43"]={["id"]=[[text43]],["text"]=[[|#AAAA不多时，她背着小药篓缓缓走入席中，你急命管家奉上一杯刚刚暖好的热酒，替她驱走了这一路而来的风寒。]]},["text44"]={["id"]=[[text44]],["text"]=[[|#AAAA岳凌薇温柔浅笑，甚是有礼地道了些“吉祥如意”的贺语，直至酒劲儿略微上脸时才同你说起近日在附近行医义诊发生的趣事。]]},["text45"]={["id"]=[[text45]],["text"]=[[|#AAAA你们相谈甚欢，后无意间提起章作之，岳凌薇长呼了一口气，指着窗外道：“看，下雪了，又是新的一年。”]]},["text46"]={["id"]=[[text46]],["text"]=[[宴席已开，你本想着一年到头管家忙碌匆匆，正准备答谢一二，谁知门外却传来了急促的敲门声。你匆匆走至大门，刚刚打开门，韩一枫和狄水清就持剑闯了进来。]]},["text47"]={["id"]=[[text47]],["text"]=[[|#AAAA你看二人风尘仆仆，恰逢门外鞭炮鸣响，也顾不得以往的那些江湖恩怨，遂道：“新春之际，你们也不安生过节，何必打打杀杀。”]]},["text48"]={["id"]=[[text48]],["text"]=[[|#AAAA狄水清当即看向韩一枫，韩一枫思量片刻后将手中之剑收了起来，对你抱拳致歉。]]},["text49"]={["id"]=[[text49]],["text"]=[[|#AAAA随后你将二人引入宴席，起初互不言语，你又命管家添酒温茶，韩一枫这才说起今日是被几个江湖弟子追杀，正好遁至此处。]]},["text5"]={["id"]=[[text5]],["text"]=[[|#AAAA他自己拿起了一侧的酒壶，用碗盛满朝你递了过来。只这一碗下肚，恰逢宴席厅外飞雪突降，似极当年关外一路冰霜。]]},["text50"]={["id"]=[[text50]],["text"]=[[|#AAAA当下管家好奇，低声向你询问与二人是何交情。你微微抬头，韩一枫已然听到此问，就替你答道：“今日，暂算江湖友人。”]]},["text51"]={["id"]=[[text51]],["text"]=[[|#AAAA你闻言，举杯道：“也罢。以此酒，为江湖友人寿，为武林同道寿。”]]},["text52"]={["id"]=[[text52]],["text"]=[[你走入席中，刚刚坐下便听得一句，“你们中原人，就是这样待客的吗？”声音自门外传来，雄浑有力，可知其内力深厚精纯。]]},["text53"]={["id"]=[[text53]],["text"]=[[|#AAAA你命管家前去一看究竟，管家刚刚打开大门，吐蕃国师就自己走了进来入了席，边道：“中原礼数繁杂，贫僧不喜。”]]},["text54"]={["id"]=[[text54]],["text"]=[[|#AAAA忽听得周围邻里喧闹起来，你也丝毫不介意，只指着满桌菜肴一一介绍，吐蕃国师看了一眼，又说这菜式小气，且先尝了一口，面上略有缓和。]]},["text55"]={["id"]=[[text55]],["text"]=[[|#AAAA许久，管家奉上美酒，吐蕃国师一口饮尽，同你道：“还以为中原皆是摇头晃脑的文弱书生，你这脾性老夫喜欢。”]]},["text56"]={["id"]=[[text56]],["text"]=[[|#AAAA是夜，你们二人品酒畅聊，一起谈论着中原与吐蕃的武学，不时还斗上一两招，甚是欢愉。]]},["text57"]={["id"]=[[text57]],["text"]=[[宴席已开，门外鞭炮齐鸣，你忽听得一曲碧海潮生暗暗传来，再出厅一望，屋顶脊梁上立着一个碧青色的人影轻按玉箫，正是东岛主。]]},["text58"]={["id"]=[[text58]],["text"]=[[|#AAAA他兀自吹箫，也不管旁人叫唤，更别说现下鞭炮吵闹。]]},["text59"]={["id"]=[[text59]],["text"]=[[|#AAAA你对着管家招了招手，命其将一坛屠苏酒抱了出来，又移出桌上菜肴，就这般席地而坐，听萧饮酒吃菜岂不快哉。]]},["text6"]={["id"]=[[text6]],["text"]=[[|#AAAA你与章作之突然相视一笑。一侧管家茫然不解，只听你们一夜从皇宫说到泰山，快意时碰碗豪饮，失意时摔坛吃肉，再后来皆酩酊大醉。]]},["text60"]={["id"]=[[text60]],["text"]=[[|#AAAA良久，一曲终了，东岛主跃下屋脊朝你走来，“哈哈哈，好极，还是你这儿清净，这次准备的酒倒和上次不一样。”]]},["text61"]={["id"]=[[text61]],["text"]=[[|#AAAA你抱拳与之大笑。东岛主兴致颇丰，足足与你论了一两个时辰，并指点了你一些武学招式。]]},["text62"]={["id"]=[[text62]],["text"]=[[|#AAAA灯影交错间，你们痛饮三杯，但不等宴席尽散东岛主忽一语不发地起身离去，你制止了管家欲拦的举动，独自笑饮起来。]]},["text63"]={["id"]=[[text63]],["text"]=[[宴上饭菜未动，听得门外有一女子正在叫门，随后管家匆匆来报，“任大小姐来了。”]]},["text64"]={["id"]=[[text64]],["text"]=[[|#AAAA不多时，只见一女子头戴面纱，手抱素琴走了进来，“闻得少侠长居此地，新春之际特来拜会。”]]},["text65"]={["id"]=[[text65]],["text"]=[[|#AAAA任大小姐轻将琴放于一侧，在管家的安排下入座席中。碗筷既动，你忽想起她曾找寻能一起琴箫合奏之人，不由问起。]]},["text66"]={["id"]=[[text66]],["text"]=[[|#AAAA任大小姐浅浅一笑，你正迷茫不知她是何意思时，她已拿起一侧的素琴来。]]},["text67"]={["id"]=[[text67]],["text"]=[[|#AAAA夜色甚好，远远听着门外长街内百姓相聚一堂后的嬉闹之声，任大小姐拨动琴弦，方才你所问似乎已然不重要。]]},["text68"]={["id"]=[[text68]],["text"]=[[|#AAAA“感谢招待，新春快乐！”]]},["text69"]={["id"]=[[text69]],["text"]=[[逢此佳节，你迫不及待地准备动筷，忽有叩门声传来，只听门外有人道：“风雪有旅客，少侠可还记得鄙人？”]]},["text7"]={["id"]=[[text7]],["text"]=[[|#AAAA你依稀记得，醉酒时曾与章作之约定：任江湖多变，来年此时仍旧饮上一夜，谈论高歌。]]},["text70"]={["id"]=[[text70]],["text"]=[[|#AAAA你快步打开屋门，邀陆千侯坐入席间，炉上的温酒已备好，你与陆千候一齐饮上了一杯，彼此开始闲谈。]]},["text71"]={["id"]=[[text71]],["text"]=[[|#AAAA陆千侯提及去年过节借屋躲雪之事，再度对你表示了感谢。一场酒宴下来，他话虽不多，却也不会令你觉得冷场。]]},["text72"]={["id"]=[[text72]],["text"]=[[|#AAAA外头风雪将停，陆千候起身离开，你欲送他出门却被他谢绝，只听他道：“承蒙款待。来日必有再会之时。”]]},["text73"]={["id"]=[[text73]],["text"]=[[屠苏酒启封，一股扑鼻的酒香传来，正是这个时候听得两声豪迈的笑声，向先生已经走入了院中。]]},["text74"]={["id"]=[[text74]],["text"]=[[|#AAAA“既有屠苏美酒，又怎能少得了我！”向先生只盯着桌上的屠苏酒道，你立即抓住坛口，用内劲儿朝他送了过去。]]},["text75"]={["id"]=[[text75]],["text"]=[[|#AAAA向先生一个转身，接过了酒坛，就此灌入口中，良久称道：“当真是好酒，少侠不妨一起。”]]},["text76"]={["id"]=[[text76]],["text"]=[[|#AAAA当下酒坛又被送了回来，你将酒坛环入怀中，随后也仰头抱坛将屠苏酒送入了口中。]]},["text77"]={["id"]=[[text77]],["text"]=[[|#AAAA酒既饮罢，你与向先生颇有默契的对视大笑，接着一起走入了屋内，配着桌上的佳肴美味饮至晨曦。]]},["text78"]={["id"]=[[text78]],["text"]=[[宴席已开，管家突然来报门前多了一个扶桑武士，身上还带有一股茶香。你猜测应是重光教的立花忠信，只是不知他为何而来。]]},["text79"]={["id"]=[[text79]],["text"]=[[|#AAAA片刻后，管家引着立花忠信到了你的面前，立花忠信面色淡然只盯着你面前的清茶不曾言语。]]},["text8"]={["id"]=[[text8]],["text"]=[[你缓缓入席，满桌佳肴便是轻嗅一口也饱了三分，正当你犹豫不知从何下筷时，宴席门口已立着一位黑市商人，只听他不温不火的问道：“今日只为寻这饭香，无货贩卖，少侠可还欢迎？”]]},["text80"]={["id"]=[[text80]],["text"]=[[|#AAAA你顺着他的目光倒了一杯茶朝他送去，笑道：“今日恰好是新春佳节，不妨同我饮上一杯。”]]},["text81"]={["id"]=[[text81]],["text"]=[[|#AAAA立花忠信向来喜欢钻研茶道，只饮一口便说出了此茶的由来，他对茶道的精通，让你心生了佩服之意。]]},["text82"]={["id"]=[[text82]],["text"]=[[|#AAAA你们由茶道起谈论各地习俗，你又向他介绍新春佳节，他听得津津有味，临走前同你道：“一期一会，这是约定。”]]},["text83"]={["id"]=[[text83]],["text"]=[[你刚刚坐入席中管家就掀开了桌旁的女儿红，谁知一根绣花银针突然从门外射入缠上了整个酒坛，随后酒坛迅速向外飞去。]]},["text84"]={["id"]=[[text84]],["text"]=[[|#AAAA管家急忙追了出去，你紧跟其后，只见门外墙瓦上一个颀长的红衣身影歪坐，正饮着方才那坛女儿红。]]},["text85"]={["id"]=[[text85]],["text"]=[[|#AAAA你抱手含笑，又命管家重新抱来一坛酒，神教教主这才朝你看来，“你这酒不错，本教主还看得上。”]]},["text86"]={["id"]=[[text86]],["text"]=[[|#AAAA“啪！啪！”听得几声被喝得空荡荡的酒壶碎地，神教教主这才起身，挑眉朝你看来，意味深长。]]},["text87"]={["id"]=[[text87]],["text"]=[[|#AAAA随后，一道烟火不知从何处点燃，你稍觉晃眼，面前的神教教主已经不知去向。]]},["text88"]={["id"]=[[text88]],["text"]=[[你刚刚准备入席，门外一声马嘶长鸣，管家没多久朝你回禀道：“家主，门外来了一男子，并非中原人士。”]]},["text89"]={["id"]=[[text89]],["text"]=[[|#AAAA你探了出去，见罗兰已经走了进来，面含笑意让人如沐春风，只听他道：“中原新春倒是很有意思，只是我走了良久，似乎你这里才有竹叶青可饮。”]]},["text9"]={["id"]=[[text9]],["text"]=[[|#AAAA管家请这位“意外之客”进门，你招了招手，同时满脸笑意地主动迎上，将黑市商人引入了席间。]]},["text90"]={["id"]=[[text90]],["text"]=[[|#AAAA既是为酒而来，你心中的戒备之意也少了许多。遂倒了一杯酒朝着罗兰送去。]]},["text91"]={["id"]=[[text91]],["text"]=[[|#AAAA罗兰轻呷一口，甚是回味，“味道果然不错，比之我们那里的酒也有过人之处。”]]},["text92"]={["id"]=[[text92]],["text"]=[[|#AAAA你微微点头，同他介绍了不少中原美酒，罗兰仔细聆听，你二人间过往的恩怨似在这一刻烟消云散。]]},["text93"]={["id"]=[[text93]],["text"]=[[新窖的剑南春被管家抬了上来，酒香浓烈，勾得你已然生津。不等管家倒出，你已抱起酒坛喝了一口，恰在此时门外有客到访。]]},["text94"]={["id"]=[[text94]],["text"]=[[|#AAAA“少侠有礼，外头风寒，想同你讨上一杯酒水暖暖身子。”面前劳伦斯彬彬有礼同你说道。]]},["text95"]={["id"]=[[text95]],["text"]=[[|#AAAA你将他请入了宴席，又命管家添上碗筷。劳伦斯轻声言谢，一品杯中酒水后朝你看来，面带谦和。]]},["text96"]={["id"]=[[text96]],["text"]=[[|#AAAA为尽地主之谊，你与他搭话，得知他经商于此，见各处中原人士为新春忙碌也生出好奇之意。]]},["text97"]={["id"]=[[text97]],["text"]=[[|#AAAA于是，你同他说了不少本地新年的习俗，劳伦斯不时点头应声，俨然不像个商人，倒像个学者。]]},["text98"]={["id"]=[[text98]],["text"]=[[|#AAAA席罢，劳伦斯起身向你道别：“新的一年，重光的光芒将遍洒这花花世界的每一片土地。多谢款待。”]]},["text99"]={["id"]=[[text99]],["text"]=[[今日宴席上多是你平日里喜欢的菜肴，不免胃口大开，于是匆匆拿起筷子，却听管家来报，有位姓程的姑娘来访。]]}},["wine"]={["wine1"]={["id"]=[[wine1]],["name"]=[[女儿红]],["text"]=[[HIR赏心乐事，历久弥新]],["wineHero"]=[[wine1Hero]],["wineText"]=[[wine1Text]]},["wine2"]={["id"]=[[wine2]],["name"]=[[竹叶青]],["text"]=[[HIG内敛醇厚，回味悠长]],["wineHero"]=[[wine2Hero]],["wineText"]=[[wine2Text]]},["wine3"]={["id"]=[[wine3]],["name"]=[[剑南春]],["text"]=[[HIC大唐御酒，甘冽豪迈]],["wineHero"]=[[wine3Hero]],["wineText"]=[[wine3Text]]},["wine4"]={["id"]=[[wine4]],["name"]=[[屠苏酒]],["text"]=[[MAG辞旧迎新，岁岁年年]],["wineHero"]=[[wine4Hero]],["wineText"]=[[wine4Text]]},["wine5"]={["id"]=[[wine5]],["name"]=[[以茶带酒]],["text"]=[[HIW君子之交，酽香如茗]],["wineHero"]=[[wine5Hero]],["wineText"]=[[wine5Text]]}}}000000000000000